import React, { useRef, useState, useEffect } from 'react';

export const WhiteboardPanel = () => {
  const canvasRef = useRef(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [color, setColor] = useState('#FFFFFF');
  const [brushSize, setBrushSize] = useState(3);
  const [tool, setTool] = useState('pen'); // pen, eraser, line, rectangle, circle
  const [startPos, setStartPos] = useState(null);
  const [tempCanvas, setTempCanvas] = useState(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#1F2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Create temp canvas for shapes
    const temp = document.createElement('canvas');
    temp.width = canvas.width;
    temp.height = canvas.height;
    setTempCanvas(temp);
  }, []);

  const getMousePos = (e) => {
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    return {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
    };
  };

  const startDrawing = (e) => {
    const pos = getMousePos(e);
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    if (tool === 'pen' || tool === 'eraser') {
      ctx.beginPath();
      ctx.moveTo(pos.x, pos.y);
    } else {
      // Save canvas state for shapes
      setStartPos(pos);
      const tempCtx = tempCanvas.getContext('2d');
      tempCtx.clearRect(0, 0, tempCanvas.width, tempCanvas.height);
      tempCtx.drawImage(canvas, 0, 0);
    }

    setIsDrawing(true);
  };

  const draw = (e) => {
    if (!isDrawing) return;

    const pos = getMousePos(e);
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    ctx.strokeStyle = tool === 'eraser' ? '#1F2937' : color;
    ctx.lineWidth = tool === 'eraser' ? brushSize * 3 : brushSize;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (tool === 'pen' || tool === 'eraser') {
      ctx.lineTo(pos.x, pos.y);
      ctx.stroke();
    } else if (startPos) {
      // Draw shapes with preview
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(tempCanvas, 0, 0);

      ctx.beginPath();
      
      if (tool === 'line') {
        ctx.moveTo(startPos.x, startPos.y);
        ctx.lineTo(pos.x, pos.y);
        ctx.stroke();
      } else if (tool === 'rectangle') {
        const width = pos.x - startPos.x;
        const height = pos.y - startPos.y;
        ctx.strokeRect(startPos.x, startPos.y, width, height);
      } else if (tool === 'circle') {
        const radius = Math.sqrt(
          Math.pow(pos.x - startPos.x, 2) + Math.pow(pos.y - startPos.y, 2)
        );
        ctx.arc(startPos.x, startPos.y, radius, 0, 2 * Math.PI);
        ctx.stroke();
      }
    }
  };

  const stopDrawing = () => {
    if (isDrawing && (tool === 'line' || tool === 'rectangle' || tool === 'circle')) {
      // Finalize shape
      const canvas = canvasRef.current;
      const tempCtx = tempCanvas.getContext('2d');
      tempCtx.clearRect(0, 0, tempCanvas.width, tempCanvas.height);
      tempCtx.drawImage(canvas, 0, 0);
    }
    setIsDrawing(false);
    setStartPos(null);
  };

  const clearCanvas = () => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#1F2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  };

  const downloadWhiteboard = () => {
    const canvas = canvasRef.current;
    const url = canvas.toDataURL('image/png');
    const a = document.createElement('a');
    a.href = url;
    a.download = `saarthi-whiteboard-${new Date().toISOString().slice(0, 10)}.png`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const colors = [
    '#FFFFFF', '#FF6B6B', '#4ECDC4', '#45B7D1', 
    '#FFA07A', '#98D8C8', '#F7DC6F', '#BB8FCE',
    '#000000', '#E74C3C', '#3498DB', '#2ECC71'
  ];

  return (
    <div className="p-4 h-full flex flex-col bg-gray-900">
      {/* Header */}
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-lg font-semibold text-white">Whiteboard</h3>
      </div>

      {/* Toolbar */}
      <div className="flex items-center justify-between mb-3 flex-wrap gap-2 bg-gray-800 p-3 rounded-lg">
        {/* Tools */}
        <div className="flex items-center gap-2">
          <button
            onClick={() => setTool('pen')}
            className={`px-3 py-2 rounded-lg font-medium text-xs transition-colors ${
              tool === 'pen' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-300'
            }`}
          >
            ✏️ Pen
          </button>
          <button
            onClick={() => setTool('eraser')}
            className={`px-3 py-2 rounded-lg font-medium text-xs transition-colors ${
              tool === 'eraser' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-300'
            }`}
          >
            🧹 Eraser
          </button>
          <button
            onClick={() => setTool('line')}
            className={`px-3 py-2 rounded-lg font-medium text-xs transition-colors ${
              tool === 'line' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-300'
            }`}
          >
            📏 Line
          </button>
          <button
            onClick={() => setTool('rectangle')}
            className={`px-3 py-2 rounded-lg font-medium text-xs transition-colors ${
              tool === 'rectangle' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-300'
            }`}
          >
            ▭ Rect
          </button>
          <button
            onClick={() => setTool('circle')}
            className={`px-3 py-2 rounded-lg font-medium text-xs transition-colors ${
              tool === 'circle' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-300'
            }`}
          >
            ⭕ Circle
          </button>
        </div>

        {/* Actions */}
        <div className="flex items-center gap-2">
          <button
            onClick={clearCanvas}
            className="px-3 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-xs font-medium transition-colors"
          >
            🗑️ Clear
          </button>
          <button
            onClick={downloadWhiteboard}
            className="px-3 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg text-xs font-medium transition-colors"
          >
            ⬇️ Save
          </button>
        </div>
      </div>

      {/* Color Picker */}
      {tool !== 'eraser' && (
        <div className="flex items-center gap-2 mb-3 bg-gray-800 p-3 rounded-lg">
          <span className="text-gray-400 text-xs font-medium">Color:</span>
          <div className="flex gap-2 flex-wrap">
            {colors.map((c) => (
              <button
                key={c}
                onClick={() => setColor(c)}
                className={`w-7 h-7 rounded-full border-2 transition-all hover:scale-110 ${
                  color === c ? 'border-blue-500 scale-110 shadow-lg' : 'border-gray-600'
                }`}
                style={{ backgroundColor: c }}
              />
            ))}
          </div>
        </div>
      )}

      {/* Brush Size */}
      <div className="flex items-center gap-3 mb-3 bg-gray-800 p-3 rounded-lg">
        <span className="text-gray-400 text-xs font-medium">
          {tool === 'eraser' ? 'Eraser' : 'Brush'} Size:
        </span>
        <input
          type="range"
          min="1"
          max="30"
          value={brushSize}
          onChange={(e) => setBrushSize(Number(e.target.value))}
          className="flex-1"
        />
        <span className="text-white text-xs w-8 font-semibold">{brushSize}px</span>
      </div>

      {/* Canvas */}
      <div className="flex-1 bg-gray-800 rounded-lg overflow-hidden border-2 border-gray-700">
        <canvas
          ref={canvasRef}
          width={1200}
          height={800}
          onMouseDown={startDrawing}
          onMouseMove={draw}
          onMouseUp={stopDrawing}
          onMouseLeave={stopDrawing}
          className="w-full h-full cursor-crosshair"
        />
      </div>
    </div>
  );
};
